import json, subprocess, datetime, sys

REPO = "cli/cli"
START = "2024-12-01"
END = "2024-12-31"

PR_QUERY = """
query($query: String!, $cursor: String) {
  search(type: ISSUE, query: $query, first: 100, after: $cursor) {
    issueCount
    pageInfo { hasNextPage endCursor }
    nodes {
      ... on PullRequest {
        number
        createdAt
        mergedAt
        closedAt
        author { login }
      }
    }
  }
}
"""

ISSUE_QUERY = """
query($query: String!, $cursor: String) {
  search(type: ISSUE, query: $query, first: 100, after: $cursor) {
    issueCount
    pageInfo { hasNextPage endCursor }
    nodes {
      ... on Issue {
        number
        createdAt
        closedAt
        labels(first: 100) { nodes { name } }
      }
    }
  }
}
"""

def gh_graphql(query, variables):
    args = ["gh", "api", "graphql", "-f", f"query={query}"]
    for k, v in variables.items():
        if v is None:
            continue
        args += ["-f", f"{k}={v}"]
    res = subprocess.run(args, capture_output=True, text=True)
    if res.returncode != 0:
        print(res.stderr, file=sys.stderr)
        raise SystemExit(res.returncode)
    return json.loads(res.stdout)

def search_all(query, gql):
    cursor = None
    nodes = []
    while True:
        data = gh_graphql(gql, {"query": query, "cursor": cursor})
        search = data["data"]["search"]
        nodes.extend([n for n in search["nodes"] if n])
        if not search["pageInfo"]["hasNextPage"]:
            break
        cursor = search["pageInfo"]["endCursor"]
    return nodes, search["issueCount"]

# PRs created in month
pr_query = f"repo:{REPO} is:pr created:{START}..{END}"
prs, pr_total = search_all(pr_query, PR_QUERY)

# Issues created in month
issue_query = f"repo:{REPO} is:issue created:{START}..{END}"
issues, issue_total = search_all(issue_query, ISSUE_QUERY)

# Bug issues closed in month (any creation date)
closed_issue_query = f"repo:{REPO} is:issue closed:{START}..{END}"
closed_issues, closed_issue_total = search_all(closed_issue_query, ISSUE_QUERY)

# PR metrics
merged_prs = [p for p in prs if p.get("mergedAt")]
closed_not_merged_prs = [p for p in prs if (p.get("closedAt") and not p.get("mergedAt"))]

# Average merge days
if merged_prs:
    total_days = 0.0
    for p in merged_prs:
        created = datetime.datetime.fromisoformat(p["createdAt"].replace("Z", "+00:00"))
        merged = datetime.datetime.fromisoformat(p["mergedAt"].replace("Z", "+00:00"))
        total_days += (merged - created).total_seconds() / 86400.0
    avg_merge_days = round(total_days / len(merged_prs), 1)
else:
    avg_merge_days = 0.0

# Top contributor by PR count
from collections import Counter

authors = []
for p in prs:
    author = p.get("author")
    if author and author.get("login"):
        authors.append(author["login"])
    else:
        authors.append("unknown")

if authors:
    counts = Counter(authors)
    top_contributor = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
else:
    top_contributor = ""

# Bug detection

def is_bug(labels):
    for lbl in labels or []:
        name = lbl.get("name", "")
        if "bug" in name.lower():
            return True
    return False

bug_issues = [i for i in issues if is_bug((i.get("labels") or {}).get("nodes", []))]
resolved_bugs = [i for i in closed_issues if is_bug((i.get("labels") or {}).get("nodes", []))]

report = {
    "pr": {
        "total": len(prs),
        "merged": len(merged_prs),
        "closed": len(closed_not_merged_prs),
        "avg_merge_days": avg_merge_days,
        "top_contributor": top_contributor,
    },
    "issue": {
        "total": len(issues),
        "bug": len(bug_issues),
        "resolved_bugs": len(resolved_bugs),
    },
}

print(json.dumps(report, indent=2))

with open("/app/report.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2)
    f.write("\n")

